// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airDrop} from "../src/airDrop.sol";

contract InvMutTest is Test {
    airDrop c;
    function setUp() public { c = new airDrop(); }

    // Fuzzed params: from address, amount v, decimals, and array length seed to build an array
    // We cannot fuzz an address callee because EOAs always succeed on low-level call; deploy a Reverter helper
    function testFuzz_property(address from, uint256 v, uint256 _decimals, uint8 tosCountSeed) public {
        // keep values in wide admissible domains
        vm.assume(from != address(0));
        uint256 decimals = bound(_decimals, 0, 18);
        uint256 value = v;
        // Build an array of recipient addresses of length between 1 and 5 so loop runs
        uint256 tosCount = uint256(bound(tosCountSeed, 1, 5));
        address[] memory tos = new address[](tosCount);
        for (uint i = 0; i < tosCount; i++) {
            // create distinct nonzero addresses via vm.addr from different derived keys
            tos[i] = vm.addr(uint256(keccak256(abi.encodePacked(from, i))));
        }

        // Deploy a helper that will revert when called; pass its address as caddress to force failing callee
        Reverter reverter = new Reverter();

        // Now call c.transfer and observe whether it reverts. For the reference contract C, because the external
        // low-level call to reverter will revert, c.transfer must revert as well (it checks the success flag and reverts).
        // The mutant that ignores the failure will instead return true (not revert). We capture whether transfer reverted.
        bool ok;
        try c.transfer(from, address(reverter), tos, value, decimals) {
            ok = true;
        } catch {
            ok = false;
        }

        // The universal property: for all admissible inputs where the callee reverts, the reference contract
        // must not return true (i.e., ok == false). This single assert reads c's observable behavior (whether call reverted).
        assertTrue(!ok);
    }
}

// Adversarial callee that ALWAYS reverts on the exact selector used by C (transferFrom(address,address,uint256))
contract Reverter {
    // Define the same function signature so calldata decodes; it then reverts.
    function transferFrom(address, address, uint256) external pure {
        revert("reverting helper");
    }
}
